function compute(p:Product,placement:ProductPlacement){
 const company={...placement.assessment,categoryVerdict:placement.opportunityTrackLabel?`${placement.opportunityTrackLabel} · ${placement.reasons.at(-1)??"已完成统一归位"}`:"垃圾箱 · 已触发硬性淘汰"};
 const dev=company.companyFit;
 const diff=Math.round((company.hiddenOpportunity*.7)+(Math.min(5,Math.max(1,p.differentiation))*20*.3));
 const market=company.demand;
 const risk=company.hardRejected?0:100;
 const total=placement.score;
 return{dev,diff,market,risk,total,reasons:company.reasons,company};
}
