 const importProducts=async(e:ChangeEvent<HTMLInputElement>)=>{
  const file=e.target.files?.[0];
  if(!file)return;
  try{
   const XLSX=await import("xlsx");
   const wb=XLSX.read(await file.arrayBuffer());
   const sheet=wb.Sheets[wb.SheetNames[0]];
   const raw=XLSX.utils.sheet_to_json<Record<string,unknown>>(sheet,{defval:""});
   attachSheetImageUrls(sheet,raw,XLSX);
   const isSellerSprite=Object.prototype.hasOwnProperty.call(raw[0]??{},"商品标题");
   const importedAt=new Date().toISOString();
   const patches=raw.map((row,index)=>{const parsed=isSellerSprite?sellerProduct(row):Object.fromEntries(fields.map(field=>[field,field==="imageUrl"?imageFromRow(row):templateCellValue(row,field)??""])) as unknown as Product;return{product:normalizeImportedProduct(parsed,importedAt),providedFields:isSellerSprite?sellerProvidedFields(row):templateProvidedFields(row),rowNumber:index+2} satisfies ProductImportPatch<Product>});
   const preview=prepareProductImport(products,patches);
   setImportPreview({fileName:file.name,patches,preview});
   setNotice(`已生成导入预览：${preview.newCount} 条新增、${preview.updateCount} 条更新、${preview.missingImageCount} 条缺图待补；确认前不会写入产品库。`)
  }catch{setImportPreview(null);setNotice("导入预览失败：请使用模板列名，并确认工作簿第一张表包含 ASIN；新产品还需要英文标题。")}finally{e.target.value=""}
 };
